package com.bank.analytics;

import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FrequencyDemo {

    private static final Logger log = Logger.getLogger(FrequencyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        String[] swipes = {
            "GROCERY", "FUEL", "GROCERY", "DINING",
            "GROCERY", "FUEL", "DINING", "GROCERY"
        };

        SwipeAnalyzer analyzer = new SwipeAnalyzer();
        Map<String, Integer> counts = analyzer.countByCategory(swipes);

        counts.forEach((category, count) ->
            log.info(() -> category + " swipes: " + count));

        log.info(() -> "Busiest category today: " + analyzer.busiestCategory(counts));
    }
}

// ─── Would be in service/SwipeAnalyzer.java in a real project ───
class SwipeAnalyzer {

    private static final Logger log = Logger.getLogger(SwipeAnalyzer.class.getName());

    // Build a frequency map in one pass: category → swipe count.
    Map<String, Integer> countByCategory(String[] swipes) {
        Map<String, Integer> frequency = new java.util.HashMap<>();
        for (String category : swipes) {
            // merge: insert 1 if absent, else add 1 to existing count.
            frequency.merge(category, 1, Integer::sum);
        }
        log.info(() -> "Counted " + swipes.length + " swipes into "
                + frequency.size() + " categories.");
        return frequency;
    }

    // Scan the map once to find the category with the highest count.
    String busiestCategory(Map<String, Integer> frequency) {
        String busiest = null;
        int max = -1;
        for (Map.Entry<String, Integer> entry : frequency.entrySet()) {
            if (entry.getValue() > max) {
                max = entry.getValue();
                busiest = entry.getKey();
            }
        }
        return busiest;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
